    public static int CalculateGCD(int x, int y) {
        if (x < y) {
            int temp;
            temp = x;
            x = y;
            y = temp;
        }
        if (x % y == 0) {
            return y;
        } else {
            return CalculateGCD(y, x % y);
        }
    }
}

