    int m = Integer.parseInt(rowIn[1]);
    int l = Integer.parseInt(rowIn[2]);

    // Initialization
    int[][] A = new int[n][m];
    int[][] B = new int[m][l];
    long[][] C = new long[n][l];
    for(int i=0; i<n; i++){
      String[] tmp = sc.nextLine().split(" ");
      for(int j=0; j<m; j++){
        A[i][j] = Integer.parseInt(tmp[j]);
      }
