    for(int i=0; i<m; i++){
      String[] tmp = sc.nextLine().split(" ");
      for(int j=0; j<l; j++){
        B[i][j] = Integer.parseInt(tmp[j]);
      }
    }

    // Matrix Multiple
    for(int i=0; i<n; i++){
      for(int j=0; j<l; j++){
        long tmp = 0;
        for(int k=0; k<m; k++){
          tmp += A[i][k] * B[k][j];
        }
        C[i][j] = tmp;
      }
