            for(int j = 0;j < l;j++){
                matrixB[i][j] = Integer.parseInt(line2[j]);
            }
        }
        //Calculate
        for(int i = 0;i < n;i++){
            for(int j = 0;j < l;j++){
                for(int k = 0;k < m;k++){
                    ansMatrix[i][j] += matrixA[i][k] * matrixB[k][j];
                }
            }
        }
        //Output
        StringBuilder sb = new StringBuilder();
        for(int i = 0;i < n;i++){
            for(int j = 0;j < l;j++){
                sb.append(ansMatrix[i][j]);
                if(j!=l-1)sb.append(" ");
            }
            if(i!=n-1)sb.append("\n");
        }
        System.out.println(sb);

    }

}

