public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s;
        Queue<Character> q = new ArrayDeque<>();

        while (true) {
            s = sc.next();
            if (s.equals("-"))
                break;

            for (int i = 0; i < s.length(); i++) {
                q.add(s.charAt(i));
            }

            int m;
