        int N = sc.nextInt();
        String str = sc.nextToken();
        int len = str.length();
        String ans = "";

        String[] strArray = str.split("");
        String[] ansArray = new String[len];

        for (int i = 0; i < len; i++) {
            ansArray[i] = proceed(N, strArray[i]);
        }

        StringBuffer sb = new StringBuffer("");
        for (int i=0; i<len; i++) {
            sb.append(ansArray[i]);
        }
        ans = sb.toString();
