            A[i] = Integer.parseInt(sc.next()) - 1; //0-indexedにしたいのであらかじめ1引いておく
        }
        int B[] = new int[N]; //Bを配列で受け取る
        for (int i= 0; i < N; i++){
            B[i] = Integer.parseInt(sc.next());
