public class Main {
	public static final int MOD = 1000000007;

    public static void main(String[] args) {
        Scanner sc = new Scanner(in);

        int n = sc.nextInt();
		int m = sc.nextInt();

		boolean[] wet = new boolean[n+1];
		Arrays.fill(wet, false);
