        ret = Math.max(ret, solve2(s.substring(i, j)));
      }
    }
    return ret;
  }

  private static int solve2(String s) {
    for(char c: s.toCharArray()) {
      if(c!='A' && c!='C' && c!='G' && c!='T') return 0;
    }
    return s.length();
  }
