            int ans = 0;
            for (int i = 0; i < q; i++) {
                int l = in.nextInt();
                int r = in.nextInt();
                l--;
                r--;
                if (l == 0) {
                    ans = p[r - 1];
                } else {
                    ans = p[r - 1] - p[l - 1];
                }
                out.println(ans);
            }
        }

    }
