		int dp[] = new int[n + 1];

		for (int i = 2; i <=n; i++) {
			dp[i] = Integer.MAX_VALUE;
			for (int j = i - 1; j >= 1 && (i - j) <= k; j--) {
				dp[i] = Math.min(dp[i], Math.abs(arr[i] - arr[j]) + dp[j]);
			}

		}
		return dp[n];

	}
