                localmin = Math.min(localmin, i - k >= 0 ? dp[i - k] + Math.abs(a[i - k] - a[i]) : dp[i - 1] + Math.abs(a[i - 1] - a[i]));
            }
            dp[i] = localmin;
        }

        out.println(dp[n-1]);

        out.flush();
        out.close();
    }


