  	static int solve(int n, int k, int[] arr){
    	int[] dp = new int[n];
      	dp[0] = 0;
        dp[1] = Math.abs(arr[0] - arr[1]);

      	for(int i = 2; i < n; i++){
        	int min = dp[i-1] + Math.abs(arr[i-1] - arr[i]);

          	for(int j = 1; j <= k; j++){
            	if(i - j < 0)
                      break;

              	int h = dp[i-j] + Math.abs(arr[i] - arr[i-j]);
              	min = (h <= min) ? h : min;
            }
          	dp[i] = min;
        }

