class Main {
	public static int frogJumpCost2(int[] arr, int n, int k) {
		int[] dp = new int[n];
		dp[n-1] = 0;
		dp[n-2] = Math.abs(arr[n-1]-arr[n-2]);
		for(int i = n-3; i >= 0; i--) {
			int min = Integer.MAX_VALUE;
			for(int j = 1; j <= k && (i+j) < n; j++) {
				int x = dp[i+j]+Math.abs(arr[i]-arr[i+j]);
				if(x < min)
					min = x;
			}
			dp[i] = min;
		}
		return dp[0];
	}
