			arr[i] = Integer.parseInt(s1[i]);
		}

		System.out.println(frogJumpCost2(arr, n, k));

	}
	public static int min(int...arr) {
		int min = Integer.MAX_VALUE;
		for(int i: arr) {
			if(i < min)
				min = i;
		}
		return min;
	}
