	private static int rec(int[] dp, int[] arr, int ind, int k) {
		// TODO Auto-generated method stub
		if(ind==arr.length-1)
		{
			return 0;
		}

		if(dp[ind]!=-1)
		{

			return dp[ind];
		}
		int n=arr.length;
		int ans=Integer.MAX_VALUE;
		for(int i=1;i<=k;i++)
		{
			if(ind+i<n)
			{
				//System.out.println(ind+" "+i);
				ans=Math.min(ans, Math.abs(arr[ind]-arr[i+ind])+rec(dp,arr,ind+i,k));
			}
		}
		dp[ind]=ans;
		return ans;
	}
}

