            for (int s = 1; s < n; s++) {
                for (int ki = 1; ki <= k && ki <= s; ki++) {
                    dp[s] = Math.min(dp[s-ki] + Math.abs(hs[s] - hs[s-ki]), dp[s]);
                }
            }
            pw.println(dp[n-1]);
        }
        pw.close();
    }

    public static void solve(long n) {

