            for (int i = 1; i <= n; i++)
                h[i] = in.nextInt();
            int[] dp = new int[n + 1];
            dp[1] = 0;
            for (int i = 2; i <= n; i++) {
                int min = Integer.MAX_VALUE;
                int v;
                for (int j = 1; j <= k; j++) {
                    if (i - j >= 1) {
                        v = dp[i - j] + Math.abs(h[i - j] - h[i]);
                        min = Math.min(min, v);
                    }
                }
                dp[i] = min;
            }
            out.println(dp[n]);
