		Scanner sc = new Scanner(System.in);
        int n = getInputInteger(sc);
		int a = getInputInteger(sc);
		int b = getInputInteger(sc);

        // programming
        int sum = 0;
        for (int i = 1; i <= n; i++) {
            int[] ds = toIntegerList(String.valueOf(i));
            int dsum = 0;
            for (int v : ds) {
                dsum += v;
            }
