class Solver {

	String solve(String inp) {

		StringBuilder sb = new StringBuilder();
		for(int i = 0;i<inp.length();i++) {
			if(inp.charAt(i)=='B' && sb.length()==0) {
				continue;
			}
			if(inp.charAt(i)=='0'||inp.charAt(i)=='1') {
				sb.append(inp.charAt(i));
			}if(inp.charAt(i)=='B') {
				sb.deleteCharAt(sb.length()-1);
			}
		}
		return sb.toString();
	}

}

